// ─────────────────────────── runtime tests ───────────────────────────────

test('parses a single unit', () => {
  eq(parseDuration('30s'), 30_000);
});

test('sums the parts of a compound duration', () => {
  eq(parseDuration('2h30m'), 9_000_000);
});

test('matches the longest unit first, so ms beats m', () => {
  eq(parseDuration('1s500ms'), 1_500);
});

test('returns null for input it cannot parse', () => {
  eq(parseDuration('soon'), null);
  eq(parseDuration(''), null);
});

test('a bare number carries no unit, so it is not a duration', () => {
  eq(parseDuration('90'), null);
});

test('isUnit recognises the four units and nothing else', () => {
  eq(isUnit('h'), true);
  eq(isUnit('y'), false);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _u1 = Expect<Equal<Unit, 'ms' | 's' | 'm' | 'h'>>;
type _u2 = Expect<Equal<ReturnType<typeof parseDuration>, number | null>>;

function _typeTests() {
  const ms: number | null = parseDuration('1h');
  use(ms);

  // @ts-expect-error — the input is a duration string, not a number
  parseDuration(1000);

  // @ts-expect-error — the result may be null, so it is not a number
  const strict: number = parseDuration('1h');
  use(strict);

  const raw: string = 'h';
  if (isUnit(raw)) {
    const narrowed: Unit = raw; // the predicate did this
    use(narrowed);
  }
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('groups by a string key', () => {
  eq(groupBy(people, (p: Person) => p.role), {
    admin: [people[0]],
    member: [people[1], people[2]],
  });
});

test('groups by a computed number key', () => {
  eq(groupBy(['a', 'bb', 'cc'], (s: string) => s.length), {
    1: ['a'],
    2: ['bb', 'cc'],
  });
});

test('keeps the input order inside each group', () => {
  const byAge = groupBy(people, (p: Person) => p.age);
  eq(byAge[36].map((p: Person) => p.name), ['ada', 'cy']);
});

test('an empty list groups into an empty object', () => {
  eq(groupBy([], (n: number) => n), {});
});

test('countBy counts instead of collecting', () => {
  eq(countBy(people, (p: Person) => p.role), { admin: 1, member: 2 });
});

// ──────────────────────────── type tests ─────────────────────────────────

type _g1 = Expect<
  Equal<ReturnType<typeof groupBy<string, 'a' | 'b'>>, Record<'a' | 'b', string[]>>
>;
type _g2 = Expect<
  Equal<ReturnType<typeof countBy<Person, string>>, Record<string, number>>
>;

function _typeTests() {
  const byRole = groupBy(people, (p) => p.role);
  const admins: Person[] = byRole.admin;
  use(admins);

  // @ts-expect-error — 'ghost' is not a key the callback can produce
  byRole.ghost;

  // @ts-expect-error — an object is not usable as a key
  groupBy(people, (p) => ({ role: p.role }));

  // @ts-expect-error — the callback is handed a Person, not a string
  groupBy(people, (p: string) => p);

  const counts = countBy(people, (p) => p.age);
  const n: number = counts[36];
  use(n);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('safeRun wraps a value that came back cleanly', () => {
  const result = safeRun(() => 6 * 7);
  eq(result.ok, true);
  if (!result.ok) throw new Error('expected the ok branch');
  eq(result.value, 42);
});

test('safeRun turns a thrown Error into the failure branch', () => {
  const result = safeRun((): number => {
    throw new RangeError('too big');
  });
  if (result.ok) throw new Error('expected the failure branch');
  eq(result.error.name, 'RangeError');
  eq(result.error.message, 'too big');
});

test('safeRun normalises a thrown string into a real Error', () => {
  const result = safeRun((): number => {
    throw 'boom';
  });
  if (result.ok) throw new Error('expected the failure branch');
  ok(result.error instanceof Error, 'expected a real Error');
  eq(result.error.message, 'boom');
});

test('toError hands a real Error straight back, untouched', () => {
  const original = new Error('keep me');
  ok(toError(original) === original, 'expected the very same object');
});

test('describe reads the extra field off each Error subclass', () => {
  eq(describe(new HttpError(404, 'gone')), 'http 404: gone');
  eq(describe(new ValidationError('email', 'is required')), 'invalid email: is required');
});

test('describe still copes with values that were never Errors', () => {
  eq(describe('boom'), 'Error: boom');
  eq(describe(404), 'Error: non-Error thrown: 404');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<
  Equal<Result<number>, { ok: true; value: number } | { ok: false; error: Error }>
>;
type _r2 = Expect<Equal<ReturnType<typeof toError>, Error>>;

function _typeTests() {
  const result = safeRun(() => 42);
  if (result.ok) {
    const value: number = result.value;
    use(value);
  } else {
    const message: string = result.error.message;
    use(message);
  }

  // @ts-expect-error — `value` exists only on the ok branch
  safeRun(() => 42).value;

  // @ts-expect-error — status appears only after narrowing to HttpError
  toError('boom').status;

  // @ts-expect-error — an HttpError needs its status before its message
  new HttpError('nope');

  const caught: unknown = null;
  // @ts-expect-error — a caught value is unknown: no property access yet
  caught.message;
  const normalised: Error = toError(caught);
  use(normalised.message);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('parses a plain numeric string', () => {
  eq(parseNum('42'), 42);
});

test('trims before parsing, and handles decimals', () => {
  eq(parseNum('  7.5 '), 7.5);
});

test('throws on junk when no options are passed', () => {
  throws(() => parseNum('abc'), 'not a number');
  throws(() => parseNum(''), 'not a number');
});

test('returns null on junk when nullable is asked for', () => {
  eq(parseNum('abc', { nullable: true }), null);
  eq(parseNum('42', { nullable: true }), 42);
});

test('toList wraps a lone value', () => {
  eq(toList(3), [3]);
  eq(toList('a'), ['a']);
});

test('toList copies an array instead of nesting it', () => {
  const input = [1, 2];
  const output = toList(input);
  eq(output, [1, 2]);
  ok(output !== input, 'expected a fresh array');
});

// ──────────────────────────── type tests ─────────────────────────────────

// ReturnType sees only the LAST overload — a real gotcha worth knowing
type _o1 = Expect<Equal<ReturnType<typeof parseNum>, number | null>>;

function _typeTests() {
  const strict: number = parseNum('42');
  const loose: number | null = parseNum('42', { nullable: true });
  use(strict, loose);

  // @ts-expect-error — with nullable: true the result may be null
  const wrong: number = parseNum('42', { nullable: true });
  use(wrong);

  // @ts-expect-error — no overload accepts a number as the text
  parseNum(42);

  // @ts-expect-error — nullable: false matches no overload
  parseNum('42', { nullable: false });

  const many: number[] = toList([1, 2]);
  const one: number[] = toList(3);
  use(many, one);

  // @ts-expect-error — the array overload must win, so this is not number[][]
  const nested: number[][] = toList([1, 2]);
  use(nested);
}
use(_typeTests);

