test('builds a node out of its tag, props and children', () => {
  const node = el('a', { href: '/x' }, 'go');
  eq(node.tag, 'a');
  eq(node.props.href, '/x');
  eq(node.children, ['go']);
});

test('renders a div, and skips an absent optional prop', () => {
  eq(render(el('div', {}, 'hi')), '<div>hi</div>');
  eq(render(el('div', { id: 'main' }, 'hi')), '<div id="main">hi</div>');
});

test('renders an anchor with its href', () => {
  eq(render(el('a', { href: '/docs' }, 'docs')), '<a href="/docs">docs</a>');
});

test('renders an img as a void element', () => {
  eq(render(el('img', { src: 'cat.png', alt: 'a cat' })), '<img src="cat.png" alt="a cat">');
});

test('renders a nested tree, strings and all', () => {
  const tree = el('div', { id: 'root' }, 'hello ', el('a', { href: '/x' }, 'x'));
  eq(render(tree), '<div id="root">hello <a href="/x">x</a></div>');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _e1 = Expect<Equal<Tag, 'div' | 'a' | 'img'>>;
type _e2 = Expect<Equal<El<'a'>['props'], { href: string }>>;
type _e3 = Expect<Equal<El<'img'>['tag'], 'img'>>;

function _typeTests() {
  const link = el('a', { href: '/x' });
  const tag: 'a' = link.tag;
  const href: string = link.props.href;
  use(tag, href);

  // @ts-expect-error — an anchor needs an href
  el('a', {});

  // @ts-expect-error — 'span' is not in the tag map
  el('span', {});

  // @ts-expect-error — src and alt belong to img, not div
  el('div', { src: 'x', alt: 'y' });

  // @ts-expect-error — a div's props have no href
  el('div', {}).props.href;
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('emit delivers the payload to every listener, in order', () => {
  const bus = new Emitter<ChatEvents>();
  const seen: string[] = [];
  bus.on('message', (text) => seen.push(`a:${text}`));
  bus.on('message', (text) => seen.push(`b:${text}`));
  bus.emit('message', 'hi');
  eq(seen, ['a:hi', 'b:hi']);
});

test('off removes exactly one listener and leaves the rest', () => {
  const bus = new Emitter<ChatEvents>();
  const seen: string[] = [];
  const first = (text: string) => seen.push(`a:${text}`);
  bus.on('message', first);
  bus.on('message', (text) => seen.push(`b:${text}`));
  bus.off('message', first);
  bus.emit('message', 'hi');
  eq(seen, ['b:hi']);
  eq(bus.listenerCount('message'), 1);
});

test('the unsubscribe returned by on does the same job', () => {
  const bus = new Emitter<ChatEvents>();
  const seen: string[] = [];
  const stop = bus.on('message', (text) => seen.push(text));
  bus.emit('message', 'one');
  stop();
  bus.emit('message', 'two');
  eq(seen, ['one']);
  eq(bus.listenerCount('message'), 0);
});

test('emitting an event nobody listens to is a quiet no-op', () => {
  const bus = new Emitter<ChatEvents>();
  bus.emit('close');
  eq(bus.listenerCount('close'), 0);
});

test('an event with an empty payload tuple still fires', () => {
  const bus = new Emitter<ChatEvents>();
  let closed = 0;
  bus.on('close', () => { closed += 1; });
  bus.emit('close');
  bus.emit('close');
  eq(closed, 2);
});

// ──────────────────────────── type tests ─────────────────────────────────

declare const typedBus: Emitter<ChatEvents>;
type _b1 = Expect<Equal<Parameters<typeof typedBus.emit<'message'>>, ['message', text: string]>>;
type _b2 = Expect<Equal<ReturnType<typeof typedBus.listenerCount<'close'>>, number>>;

function _typeTests() {
  const bus = new Emitter<ChatEvents>();

  bus.on('message', (text) => {
    const inferred: string = text;
    use(inferred);
  });

  // @ts-expect-error — 'closed' is not an event on this bus
  bus.on('closed', () => {});

  // @ts-expect-error — message needs its string payload
  bus.emit('message');

  // @ts-expect-error — the message payload is a string, not a number
  bus.emit('message', 1);

  // @ts-expect-error — close carries no payload at all
  bus.emit('close', 1);

  // @ts-expect-error — the listener is handed a string, not a number
  bus.on('message', (text: number) => use(text));
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('GET /users returns the whole list', async () => {
  const client = createClient(createFakeFetcher());
  const users = await client.request('GET /users', { query: {} });
  eq(users.map((u: User) => u.name), ['ada', 'bo', 'cy']);
});

test('GET /users narrows on the query it was given', async () => {
  const client = createClient(createFakeFetcher());
  const admins = await client.request('GET /users', { query: { role: 'admin' } });
  eq(admins.length, 1);
  eq(admins[0].name, 'ada');
});

test('GET /users/:id returns exactly one user', async () => {
  const client = createClient(createFakeFetcher());
  const user = await client.request('GET /users/:id', { params: { id: 2 } });
  eq(user.name, 'bo');
});

test('POST /users creates a user the next GET can see', async () => {
  const client = createClient(createFakeFetcher());
  const created = await client.request('POST /users', {
    body: { name: 'dee', role: 'member' },
  });
  eq(created.id, 4);
  const users = await client.request('GET /users', { query: {} });
  eq(users.length, 4);
});

test('DELETE /users/:id reports how many rows went', async () => {
  const client = createClient(createFakeFetcher());
  eq(await client.request('DELETE /users/:id', { params: { id: 1 } }), { deleted: 1 });
  eq(await client.request('DELETE /users/:id', { params: { id: 1 } }), { deleted: 0 });
});

test('a transport failure surfaces as a rejection', async () => {
  const client = createClient(createFakeFetcher());
  await rejects(client.request('GET /users/:id', { params: { id: 99 } }), 'no user 99');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _a1 = Expect<Equal<ResponseOf<'GET /users'>, User[]>>;
type _a2 = Expect<Equal<ResponseOf<'DELETE /users/:id'>, { deleted: number }>>;
type _a3 = Expect<Equal<InitOf<'POST /users'>, { body: NewUser }>>;

async function _typeTests() {
  const client = createClient(createFakeFetcher());

  const users: User[] = await client.request('GET /users', { query: {} });
  const one: User = await client.request('GET /users/:id', { params: { id: 1 } });
  use(users, one);

  // @ts-expect-error — there is no such endpoint in the map
  client.request('GET /nope', {});

  // @ts-expect-error — POST /users needs a body
  client.request('POST /users', {});

  // @ts-expect-error — a user id is a number
  client.request('GET /users/:id', { params: { id: '1' } });

  // @ts-expect-error — GET /users answers with a list, not one user
  const wrong: User = await client.request('GET /users', { query: {} });
  use(wrong);
}
use(_typeTests);

