// ─────────────────────────── runtime tests ───────────────────────────────

test('builds a config from the required keys plus defaults', () => {
  const config = configBuilder().set('host', 'db.local').set('port', 5432).build();
  eq(config, { host: 'db.local', port: 5432, secure: false, retries: 3 });
});

test('optional keys override the defaults', () => {
  const config = configBuilder()
    .set('host', 'x')
    .set('port', 1)
    .set('secure', true)
    .set('retries', 0)
    .build();
  eq(config.secure, true);
  eq(config.retries, 0);
});

test('setting the same key twice keeps the last value', () => {
  const config = configBuilder()
    .set('host', 'first')
    .set('port', 1)
    .set('host', 'second')
    .build();
  eq(config.host, 'second');
});

test('order does not matter, only coverage', () => {
  const config = configBuilder().set('port', 80).set('host', 'a').build();
  eq(config, { host: 'a', port: 80, secure: false, retries: 3 });
});

test('two builders do not share state', () => {
  const first = configBuilder().set('host', 'a').set('port', 1);
  const second = configBuilder().set('host', 'b').set('port', 2);
  eq(first.build().host, 'a');
  eq(second.build().host, 'b');
  ok(first.build() !== second.build(), 'expected separate configs');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _b1 = Expect<
  Equal<Builder<'host' | 'port'> extends { build(): Config } ? true : false, true>
>;
type _b2 = Expect<
  Equal<Builder<'host'> extends { build(): Config } ? true : false, false>
>;

function _typeTests() {
  const config: Config = configBuilder().set('host', 'x').set('port', 1).build();
  use(config);

  // @ts-expect-error — nothing has been set yet, so there is no build()
  configBuilder().build();

  // @ts-expect-error — host alone is not enough
  configBuilder().set('host', 'x').build();

  // @ts-expect-error — port is a number
  configBuilder().set('port', '8080');

  // @ts-expect-error — 'protocol' is not a config key
  configBuilder().set('protocol', 'https');
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('a single step follows the map', () => {
  eq(transition('idle', 'FETCH'), 'loading');
  eq(transition('loading', 'RESOLVE'), 'ready');
});

test('a whole session walks through the machine', () => {
  const loading = transition('idle', 'FETCH');
  const failed = transition(loading, 'REJECT');
  const retrying = transition(failed, 'RETRY');
  const ready = transition(retrying, 'RESOLVE');
  eq([loading, failed, retrying, ready], ['loading', 'failed', 'loading', 'ready']);
});

test('two states can share an event name and still differ', () => {
  eq(transition('ready', 'CLEAR'), 'idle');
  eq(transition('failed', 'CLEAR'), 'idle');
  eq(transition('ready', 'REFRESH'), 'loading');
});

test('canTransition answers for events that came in as plain strings', () => {
  eq(canTransition('idle', 'FETCH'), true);
  eq(canTransition('idle', 'RESOLVE'), false);
  eq(canTransition('loading', 'nonsense'), false);
});

test('eventsFor lists what a state accepts', () => {
  eq(eventsFor('loading'), ['RESOLVE', 'REJECT']);
  eq(eventsFor('idle'), ['FETCH']);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _s1 = Expect<Equal<State, 'idle' | 'loading' | 'ready' | 'failed'>>;
type _s2 = Expect<Equal<EventFor<'ready'>, 'REFRESH' | 'CLEAR'>>;
type _s3 = Expect<Equal<NextState<'loading', 'RESOLVE'>, 'ready'>>;
type _s4 = Expect<Equal<NextState<'failed', 'RETRY'>, 'loading'>>;

function _typeTests() {
  const next: 'ready' = transition('loading', 'RESOLVE');
  use(next);

  // @ts-expect-error — RESOLVE is not an event of idle
  transition('idle', 'RESOLVE');

  // @ts-expect-error — 'done' is not a state
  transition('done', 'FETCH');

  // @ts-expect-error — the machine has no CANCEL event anywhere
  transition('loading', 'CANCEL');
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('firstLine reads the first line of a present string', () => {
  eq(firstLine('alpha\nbeta'), 'alpha');
  eq(firstLine('only'), 'only');
});

test('firstLine throws, naming the label it was given', () => {
  throws(() => firstLine(null), 'text is null');
  throws(() => firstLine(undefined), 'text is undefined');
});

test('readSettings hands back an object that matches the schema', () => {
  const raw: unknown = JSON.parse('{"theme":"dark","fontSize":14,"compact":false}');
  eq(readSettings(raw), { theme: 'dark', fontSize: 14, compact: false });
});

test('readSettings ignores keys the schema never mentioned', () => {
  const raw: unknown = { theme: 'dark', fontSize: 14, compact: false, extra: 1 };
  ok(readSettings(raw).theme === 'dark', 'expected the extra key to be tolerated');
});

test('readSettings names the field that was wrong', () => {
  throws(() => readSettings({ theme: 42, fontSize: 14, compact: false }), 'theme must be a string');
  throws(() => readSettings({ theme: 'dark', fontSize: '14', compact: false }), 'fontSize must be a number');
});

test('readSettings rejects things that are not objects at all', () => {
  throws(() => readSettings(null), 'expected an object');
  throws(() => readSettings('dark'), 'expected an object');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _s1 = Expect<
  Equal<ShapeOf<{ a: 'string'; b: 'number'; c: 'boolean' }>, { a: string; b: number; c: boolean }>
>;

function _typeTests() {
  const maybe = Math.random() > 0.5 ? 'value' : null;
  // @ts-expect-error — not narrowed yet: it may still be null
  maybe.toUpperCase();
  assertDefined(maybe);
  const sure: string = maybe;
  use(sure);

  const json: unknown = JSON.parse('{}');
  // @ts-expect-error — you cannot read a property off unknown
  json.theme;
  assertShape(json, { theme: 'string' } as const);
  const theme: string = json.theme;
  use(theme);

  // @ts-expect-error — 'str' is not one of the field types
  assertShape({}, { name: 'str' });
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('get returns what it was created with', () => {
  const store = createStore(initialState);
  eq(store.get(), { count: 0, user: { name: 'ada' } });
});

test('set replaces the state, in both forms', () => {
  const store = createStore(initialState);
  store.set({ count: 5, user: { name: 'bo' } });
  eq(store.get().count, 5);
  store.set((prev: AppState) => ({ ...prev, count: prev.count + 1 }));
  eq(store.get().count, 6);
  eq(store.get().user.name, 'bo');
});

test('select projects without subscribing to anything', () => {
  const store = createStore(initialState);
  eq(store.select((s: AppState) => s.user.name), 'ada');
  eq(store.select((s: AppState) => s.count * 2), 0);
});

test('a subscriber fires only when its own slice changes', () => {
  const store = createStore(initialState);
  const seen: string[] = [];
  store.subscribe((s: AppState) => s.user.name, (name: string) => seen.push(name));
  store.set((prev: AppState) => ({ ...prev, count: prev.count + 1 }));
  eq(seen, []);
  store.set((prev: AppState) => ({ ...prev, user: { name: 'bo' } }));
  eq(seen, ['bo']);
});

test('the listener is handed the new value and the old one', () => {
  const store = createStore(initialState);
  const pairs: string[] = [];
  store.subscribe(
    (s: AppState) => s.count,
    (next: number, previous: number) => pairs.push(`${previous}->${next}`)
  );
  store.set({ count: 1, user: { name: 'ada' } });
  store.set({ count: 7, user: { name: 'ada' } });
  eq(pairs, ['0->1', '1->7']);
});

test('unsubscribing stops the notifications', () => {
  const store = createStore(initialState);
  let hits = 0;
  const stop = store.subscribe((s: AppState) => s.count, () => { hits += 1; });
  store.set({ count: 1, user: { name: 'ada' } });
  stop();
  store.set({ count: 2, user: { name: 'ada' } });
  eq(hits, 1);
  ok(store.get().count === 2, 'the store itself keeps updating');
});

// ──────────────────────────── type tests ─────────────────────────────────

declare const typedStore: Store<AppState>;
type _t1 = Expect<Equal<ReturnType<typeof typedStore.get>, AppState>>;
