//  11 · a store with typed selectors                       ★★☆ core
//  concepts: inference through callbacks · a second type param on a method
//  run: node ../run.js exercises/11-store-with-selectors.ts
// ─────────────────────────────────────────────────────────────────────────
//
//  Every state library — Redux, Zustand, Jotai — is this closure with a
//  nicer name. What makes it pleasant to use is that the SELECTOR carries
//  the types: you pass `s => s.user.name`, and `R` is inferred as
//  `string` without anyone writing an annotation.
//
//      const store = createStore({ count: 0, user: { name: 'ada' } });
//      store.get()                          → the whole state
//      store.set({ ...s, count: 1 })        → replace it
//      store.set(prev => ({ ...prev, count: prev.count + 1 }))
//      store.select(s => s.count)           → number
//      store.subscribe(s => s.user.name, (name, previous) => ...)
//                                           → fires ONLY when name changes
//
//  `subscribe` returns an unsubscribe function and compares with
//  `Object.is`, so a set that leaves the selected slice alone is silent.
//  That "only when my slice changes" behaviour is the point of the whole
//  pattern, and it is what the runtime tests check.
//
//  hint: `S` belongs to the store, `R` belongs to the individual method —
//  `select<R>(selector: (state: S) => R): R`. Also: `typeof updater ===
//  'function'` is the sane way to accept both forms, and it is why a
//  store whose state IS a function needs a different API

import { test, eq, ok } from '../../_lib/check.ts';
import { use, type Expect, type Equal } from '../../_lib/type-assert.ts';

type TODO = any; // replace every TODO below with real types

export interface Store<S> {
  get: TODO;
  set: TODO;
  select: TODO;
  subscribe: TODO;
}

export function createStore(initial: TODO): TODO {
  throw new Error('TODO');
}

interface AppState {
  count: number;
  user: { name: string };
}

const initialState: AppState = { count: 0, user: { name: 'ada' } };

// ─────────────────────────── runtime tests ───────────────────────────────

test('get returns what it was created with', () => {
  const store = createStore(initialState);
  eq(store.get(), { count: 0, user: { name: 'ada' } });
});

test('set replaces the state, in both forms', () => {
  const store = createStore(initialState);
  store.set({ count: 5, user: { name: 'bo' } });
  eq(store.get().count, 5);
  store.set((prev: AppState) => ({ ...prev, count: prev.count + 1 }));
  eq(store.get().count, 6);
  eq(store.get().user.name, 'bo');
});

test('select projects without subscribing to anything', () => {
  const store = createStore(initialState);
  eq(store.select((s: AppState) => s.user.name), 'ada');
  eq(store.select((s: AppState) => s.count * 2), 0);
});

test('a subscriber fires only when its own slice changes', () => {
  const store = createStore(initialState);
  const seen: string[] = [];
  store.subscribe((s: AppState) => s.user.name, (name: string) => seen.push(name));
  store.set((prev: AppState) => ({ ...prev, count: prev.count + 1 }));
  eq(seen, []);
  store.set((prev: AppState) => ({ ...prev, user: { name: 'bo' } }));
  eq(seen, ['bo']);
});

test('the listener is handed the new value and the old one', () => {
  const store = createStore(initialState);
  const pairs: string[] = [];
  store.subscribe(
    (s: AppState) => s.count,
    (next: number, previous: number) => pairs.push(`${previous}->${next}`)
  );
  store.set({ count: 1, user: { name: 'ada' } });
  store.set({ count: 7, user: { name: 'ada' } });
  eq(pairs, ['0->1', '1->7']);
});

test('unsubscribing stops the notifications', () => {
  const store = createStore(initialState);
  let hits = 0;
  const stop = store.subscribe((s: AppState) => s.count, () => { hits += 1; });
  store.set({ count: 1, user: { name: 'ada' } });
  stop();
  store.set({ count: 2, user: { name: 'ada' } });
  eq(hits, 1);
  ok(store.get().count === 2, 'the store itself keeps updating');
});

