});

test('tableTest names the cases that failed', () => {
  const report = tableTest(add, [
    { name: 'adds', args: [1, 2], expected: 3 },
    { name: 'wrong', args: [1, 2], expected: 4 },
    { name: 'also wrong', args: [2, 2], expected: 5 },
  ]);
